42	/**
43	 * Generates an implementation of the Jackson's {@code StdSerializer} for each class that needs to be serialized in json.
44	 * In this way the serialization process can be performed through the ad-hoc generate serializer and then without
45	 * any use of reflection. For instance for a pojo like this
46	 *
47	 * <pre>{@code
48	 * public class Person {
49	 *     private String firstName;
50	 *
51	 *     &#64;JsonProperty("familyName")
52	 *     private String lastName;
53	 *
54	 *     private int age;
55	 *
56	 *     &#64;SecureField(rolesAllowed = "admin")
57	 *     private Address address;
58	 *
59	 *     public Person() {
60	 *     }
61	 *
62	 *     public Person(String firstName, String lastName, int age, Address address) {
63	 *         this.firstName = firstName;
64	 *         this.lastName = lastName;
65	 *         this.age = age;
66	 *         this.address = address;
67	 *     }
68	 *
69	 *     // getters and setters omitted
70	 * }
71	 * }</pre>
72	 *
73	 * it generates the following {@code StdSerializer} implementation
74	 *
75	 * <pre>{@code
76	 * public class Person$quarkusjacksonserializer extends StdSerializer {
77	 *     static final String[] address_ROLES_ALLOWED = new String[] { "admin" };
78	 *
79	 *     public Person$quarkusjacksonserializer() {
80	 *         super(Person.class);
81	 *     }
82	 *
83	 *     public void serialize(Object var1, JsonGenerator var2, SerializerProvider var3) throws IOException {
84	 *         Person var4 = (Person) var1;
85	 *         var2.writeStartObject();
86	 *         var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.age);
87	 *         int var5 = var4.getAge();
88	 *         var2.writeNumber(var5);
89	 *         var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.firstName);
90	 *         String var6 = var4.getFirstName();
91	 *         var2.writeString(var6);
92	 *         var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.familyName);
93	 *         String var7 = var4.getLastName();
94	 *         var2.writeString(var7);
95	 *         if (JacksonMapperUtil.includeSecureField(address_ROLES_ALLOWED)) {
96	 *             var2.writeFieldName(SerializedStrings$quarkusjacksonserializer.address);
97	 *             Address var9 = var4.getAddress();
98	 *             var2.writePOJO(var9);
99	 *         }
100	 *         var2.writeEndObject();
101	 *     }
102	 * }
103	 *
104	 * public class SerializedStrings$quarkusjacksonserializer {
105	 *     static final SerializedString age = new SerializedString("age");
106	 *     static final SerializedString firstName = new SerializedString("firstName");
107	 *     static final SerializedString familyName = new SerializedString("familyName");
108	 *     static final SerializedString address = new SerializedString("address");
109	 * }
110	 * }</pre>
111	 *
112	 * Here, for performance reasons, the names of the fields to be serialized is stored as Jackson's {@code SerializedString}s
113	 * in an external class, and reused for each serialization, thus avoiding executing the UTF-8 encoding of the same strings
114	 * at each serialization.
115	 *
116	 * Note that in this case also the {@code Address} class has to be serialized in the same way, and then this factory triggers
117	 * the generation of a second StdSerializer also for it. More in general if during the generation of a serializer for a
118	 * given class it discovers a non-primitive field of another type for which a serializer hasn't been generated yet, this
119	 * factory enqueues a code generation also for that type. The same is valid for both arrays of that type, like
120	 * {@code Address[]}, and collections, like {@code List&lt;Address&gt}.
121	 */
122	public class JacksonSerializerFactory extends JacksonCodeGenerator {
123	
124	    private static final String CLASS_NAME_SUFFIX = "$quarkusjacksonserializer";
125	    private static final String SUPER_CLASS_NAME = StdSerializer.class.getName();
126	    private static final String JSON_GEN_CLASS_NAME = JsonGenerator.class.getName();
127	    private static final String SER_STRINGS_CLASS_NAME = "SerializedStrings$quarkusjacksonserializer";
128	
129	    private final Map<String, Set<String>> generatedFields = new HashMap<>();
130	
131	    public JacksonSerializerFactory(BuildProducer<GeneratedClassBuildItem> generatedClassBuildItemBuildProducer,
132	            IndexView jandexIndex) {
133	        super(generatedClassBuildItemBuildProducer, jandexIndex);
134	    }
135	
136	    @Override
137	    public Collection<String> create(Collection<ClassInfo> classInfos) {
138	        Collection<String> createdClasses = super.create(classInfos);
139	        createFieldNamesClass();
140	        return createdClasses;
141	    }
142	
143	    private void createFieldNamesClass() {
144	        if (generatedFields.isEmpty()) {
145	            return;
146	        }
147	
148	        MethodDescriptor serStringCtor = MethodDescriptor.ofConstructor(SerializedString.class, String.class);
149	
150	        for (Map.Entry<String, Set<String>> fieldsInPkg : generatedFields.entrySet()) {
151	            try (ClassCreator classCreator = new ClassCreator(
152	                    new GeneratedClassGizmoAdaptor(generatedClassBuildItemBuildProducer, true),
153	                    fieldsInPkg.getKey() + "." + SER_STRINGS_CLASS_NAME, null,
154	                    "java.lang.Object")) {
155	
156	                MethodCreator clinit = classCreator.getMethodCreator("<clinit>", void.class).setModifiers(ACC_STATIC);
157	
158	                for (String field : fieldsInPkg.getValue()) {
159	                    FieldCreator fieldCreator = classCreator.getFieldCreator(field, SerializedString.class.getName())
160	                            .setModifiers(ACC_STATIC | ACC_FINAL);
161	                    clinit.writeStaticField(fieldCreator.getFieldDescriptor(),
162	                            clinit.newInstance(serStringCtor, clinit.load(field)));
163	                }
164	
165	                clinit.returnVoid();
166	            }
167	        }
168	    }
169	
