39	public abstract class JacksonCodeGenerator {
40	    protected final BuildProducer<GeneratedClassBuildItem> generatedClassBuildItemBuildProducer;
41	    protected final IndexView jandexIndex;
42	
43	    protected final Set<String> generatedClassNames = new HashSet<>();
44	    protected final Deque<ClassInfo> toBeGenerated = new ArrayDeque<>();
45	
46	    public JacksonCodeGenerator(BuildProducer<GeneratedClassBuildItem> generatedClassBuildItemBuildProducer,
47	            IndexView jandexIndex) {
48	        this.generatedClassBuildItemBuildProducer = generatedClassBuildItemBuildProducer;
49	        this.jandexIndex = jandexIndex;
50	    }
51	
52	    protected abstract String getSuperClassName();
53	
54	    protected String[] getInterfacesNames(ClassInfo classInfo) {
55	        return new String[0];
56	    }
57	
58	    protected abstract String getClassSuffix();
59	
60	    public Collection<String> create(Collection<ClassInfo> classInfos) {
61	        Set<String> createdClasses = new HashSet<>();
62	        toBeGenerated.addAll(classInfos);
63	
64	        while (!toBeGenerated.isEmpty()) {
65	            create(toBeGenerated.removeFirst()).ifPresent(createdClasses::add);
66	        }
67	
68	        return createdClasses;
69	    }
70	
71	    private Optional<String> create(ClassInfo classInfo) {
72	        String beanClassName = classInfo.name().toString();
73	        if (vetoedClass(classInfo, beanClassName) || !generatedClassNames.add(beanClassName)) {
74	            return Optional.empty();
75	        }
76	
77	        String generatedClassName = beanClassName + getClassSuffix();
78	
79	        try (ClassCreator classCreator = new ClassCreator(
80	                new GeneratedClassGizmoAdaptor(generatedClassBuildItemBuildProducer, true), generatedClassName, null,
81	                getSuperClassName(), getInterfacesNames(classInfo))) {
82	
83	            createConstructor(classCreator, beanClassName);
84	            boolean valid = createSerializationMethod(classInfo, classCreator, beanClassName);
85	            return valid ? Optional.of(generatedClassName) : Optional.empty();
86	        }
87	    }
88	
89	    private void createConstructor(ClassCreator classCreator, String beanClassName) {
90	        MethodCreator constructor = classCreator.getConstructorCreator(new String[0]);
91	        constructor.invokeSpecialMethod(
92	                MethodDescriptor.ofConstructor(getSuperClassName(), "java.lang.Class"),
93	                constructor.getThis(), constructor.loadClass(beanClassName));
94	        constructor.returnVoid();
95	    }
96	
97	    protected abstract boolean createSerializationMethod(ClassInfo classInfo, ClassCreator classCreator, String beanClassName);
98	
99	    protected Collection<FieldInfo> classFields(ClassInfo classInfo) {
100	        Collection<FieldInfo> fields = new ArrayList<>();
101	        classFields(classInfo, fields);
102	        return fields;
103	    }
104	
105	    protected void classFields(ClassInfo classInfo, Collection<FieldInfo> fields) {
106	        fields.addAll(classInfo.fields());
107	        onSuperClass(classInfo, superClassInfo -> {
108	            classFields(superClassInfo, fields);
109	            return null;
110	        });
111	    }
112	
113	    protected <T> T onSuperClass(ClassInfo classInfo, Function<ClassInfo, T> f) {
114	        Type superType = classInfo.superClassType();
115	        if (superType != null && !vetoedClassName(superType.name().toString())) {
116	            ClassInfo superClassInfo = jandexIndex.getClassByName(superType.name());
117	            if (superClassInfo != null) {
118	                return f.apply(superClassInfo);
119	            }
120	        }
121	        return null;
122	    }
123	
124	    protected Collection<MethodInfo> classMethods(ClassInfo classInfo) {
125	        Collection<MethodInfo> methods = new ArrayList<>();
126	        classMethods(classInfo, methods);
127	        return methods;
128	    }
129	
130	    private void classMethods(ClassInfo classInfo, Collection<MethodInfo> methods) {
131	        methods.addAll(classInfo.methods());
132	        onSuperClass(classInfo, superClassInfo -> {
133	            classMethods(superClassInfo, methods);
134	            return null;
135	        });
136	    }
137	
138	    protected MethodInfo findMethod(ClassInfo classInfo, String methodName, Type... parameters) {
139	        MethodInfo method = classInfo.method(methodName, parameters);
140	        return method != null ? method
